function g06ExportGenericSkills(result=aiBatchPreview){const entries=Array.isArray(result?.entries)?result.entries:[],accepted=entries.filter(x=>x?.status==='ACCEPT'&&x?.skill).map(x=>({index:x.index,skill:clone(x.skill),generation:clone(x.generation||{}),validation:{budgetResult:clone(x.validation?.budgetResult||null),compilerWarnings:clone(x.validation?.compilerWarnings||[])}}));if(!accepted.length)throw Object.assign(new Error('G06 Export対象のACCEPT Skillがありません'),{code:'G06_GENERIC_EXPORT_EMPTY'});return{schema:'GKS_GENERIC_SKILL_BATCH',version:G06_JSON_VERSION,sourceSchema:result?.schema||'GKS_GENERIC_SKILL_AI_BATCH_RESULT',aiGenerationRuleVersion:result?.aiGenerationRuleVersion||'',budgetRuleVersion:result?.budgetRuleVersion||'',skills:accepted};}
function g06ExportValidationReport(result=aiBatchPreview){const entries=Array.isArray(result?.entries)?result.entries:[];if(!entries.length)throw Object.assign(new Error('G06 Validation Report対象がありません'),{code:'G06_VALIDATION_EXPORT_EMPTY'});return{schema:'GKS_GENERIC_SKILL_VALIDATION_REPORT',version:G06_JSON_VERSION,aiGenerationRuleVersion:result?.aiGenerationRuleVersion||'',budgetRuleVersion:result?.budgetRuleVersion||'',summary:clone(result?.summary||{}),entries:entries.map(x=>({index:x.index,status:x.status,skillId:x.skill?.id||null,request:clone(x.request||null),issues:clone(x.validation?.issues||[]),gates:{registry:!!x.validation?.registry,budget:!!x.validation?.budget,compiler:!!x.validation?.compiler}}))};}
