function generateRecord(input){const d=clone(input);d.logics=Array.isArray(d.logics)?d.logics:[];const validation=validateDraft(d);const tags=buildTags(d);const logicOrder=(spec.logic_order||[]).filter(x=>d.logics.includes(x));const now=stamp();const record={id:String(d.id||''),name:String(d.name||''),status:String(d.status||'development'),tags,params:{skill_generation:{generator:'GKSSkillGenerator',generator_version:VERSION,runtime_requirements_version:spec.version,skill_level:Number(d.skill_level)||0,logic_order_expected:logicOrder,search_tags:Array.isArray(d.searchTags)?d.searchTags:String(d.searchTags||'').split(',').map(x=>x.trim()).filter(Boolean),source_input:clone(d)}},description:String(d.description||''),created_at:d.created_at||now,updated_at:now};return {input:d,record,validation:{...validation,logicOrder}};}
