 if(!report.summary.allAccepted)throw Object.assign(new Error(`G07登録拒否: Generic再Validation REJECT ${report.summary.rejected} / root issues ${report.summary.rootIssueCount}`),{code:'G07_REVALIDATION_REJECT',report});
